// aes-core.mjs
// Pure-JavaScript AES-128 block cipher (encryption direction only),
// reimplemented from the AES specification (FIPS-197) behavior.
// No external or built-in crypto modules are used.

// AES S-box (substitution box)
const SBOX = new Uint8Array([
  0x63, 0x7c, 0x77, 0x7b, 0xf2, 0x6b, 0x6f, 0xc5, 0x30, 0x01, 0x67, 0x2b, 0xfe, 0xd7, 0xab, 0x76,
