  0xb7, 0xfd, 0x93, 0x26, 0x36, 0x3f, 0xf7, 0xcc, 0x34, 0xa5, 0xe5, 0xf1, 0x71, 0xd8, 0x31, 0x15,
  0x04, 0xc7, 0x23, 0xc3, 0x18, 0x96, 0x05, 0x9a, 0x07, 0x12, 0x80, 0xe2, 0xeb, 0x27, 0xb2, 0x75,
  0x09, 0x83, 0x2c, 0x1a, 0x1b, 0x6e, 0x5a, 0xa0, 0x52, 0x3b, 0xd6, 0xb3, 0x29, 0xe3, 0x2f, 0x84,
  0x53, 0xd1, 0x00, 0xed, 0x20, 0xfc, 0xb1, 0x5b, 0x6a, 0xcb, 0xbe, 0x39, 0x4a, 0x4c, 0x58, 0xcf,
  0xd0, 0xef, 0xaa, 0xfb, 0x43, 0x4d, 0x33, 0x85, 0x45, 0xf9, 0x02, 0x7f, 0x50, 0x3c, 0x9f, 0xa8,
  0x51, 0xa3, 0x40, 0x8f, 0x92, 0x9d, 0x38, 0xf5, 0xbc, 0xb6, 0xda, 0x21, 0x10, 0xff, 0xf3, 0xd2,
  0xcd, 0x0c, 0x13, 0xec, 0x5f, 0x97, 0x44, 0x17, 0xc4, 0xa7, 0x7e, 0x3d, 0x64, 0x5d, 0x19, 0x73,
  0x60, 0x81, 0x4f, 0xdc, 0x22, 0x2a, 0x90, 0x88, 0x46, 0xee, 0xb8, 0x14, 0xde, 0x5e, 0x0b, 0xdb,
  0xe0, 0x32, 0x3a, 0x0a, 0x49, 0x06, 0x24, 0x5c, 0xc2, 0xd3, 0xac, 0x62, 0x91, 0x95, 0xe4, 0x79,
  0xe7, 0xc8, 0x37, 0x6d, 0x8d, 0xd5, 0x4e, 0xa9, 0x6c, 0x56, 0xf4, 0xea, 0x65, 0x7a, 0xae, 0x08,
  0xba, 0x78, 0x25, 0x2e, 0x1c, 0xa6, 0xb4, 0xc6, 0xe8, 0xdd, 0x74, 0x1f, 0x4b, 0xbd, 0x8b, 0x8a,
  0x70, 0x3e, 0xb5, 0x66, 0x48, 0x03, 0xf6, 0x0e, 0x61, 0x35, 0x57, 0xb9, 0x86, 0xc1, 0x1d, 0x9e,
  0xe1, 0xf8, 0x98, 0x11, 0x69, 0xd9, 0x8e, 0x94, 0x9b, 0x1e, 0x87, 0xe9, 0xce, 0x55, 0x28, 0xdf,
  0x8c, 0xa1, 0x89, 0x0d, 0xbf, 0xe6, 0x42, 0x68, 0x41, 0x99, 0x2d, 0x0f, 0xb0, 0x54, 0xbb, 0x16,
]);

// Round constants for AES-128 key expansion
const RCON = new Uint8Array([0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36]);

// Multiply by 2 in GF(2^8) ("xtime")
function xtime(a) {
  return ((a << 1) ^ ((a & 0x80) ? 0x1b : 0x00)) & 0xff;
}

export class AESBlockCipher {
  /**
   * @param {Uint8Array} key - 16-byte AES-128 key
   */
  constructor(key) {
    if (key.length !== 16) {
      throw new Error('AES-128 key must be exactly 16 bytes');
    }
    // Expand the 16-byte key into 11 round keys (176 bytes)
    const expanded = new Uint8Array(176);
    expanded.set(key, 0);
    let bytesGenerated = 16;
    let rconIndex = 0;
    const temp = new Uint8Array(4);
    while (bytesGenerated < 176) {
      for (let i = 0; i < 4; i++) temp[i] = expanded[bytesGenerated - 4 + i];
      if (bytesGenerated % 16 === 0) {
        // RotWord
        const t = temp[0];
        temp[0] = temp[1]; temp[1] = temp[2]; temp[2] = temp[3]; temp[3] = t;
        // SubWord
        for (let i = 0; i < 4; i++) temp[i] = SBOX[temp[i]];
        // XOR with Rcon
        temp[0] ^= RCON[rconIndex++];
      }
      for (let i = 0; i < 4; i++) {
        expanded[bytesGenerated] = expanded[bytesGenerated - 16] ^ temp[i];
        bytesGenerated++;
      }
    }
    this._roundKeys = expanded;
  }

  /**
   * Encrypt one 16-byte block.
   * @param {Uint8Array} block - 16-byte plaintext block
   * @returns {Uint8Array} 16-byte ciphertext block
   */
  encryptBlock(block) {
    if (block.length !== 16) {
      throw new Error('AES block must be exactly 16 bytes');
    }
    // State in column-major order: state[c*4 + r]
    const state = new Uint8Array(block);
    const rk = this._roundKeys;

    this._addRoundKey(state, 0);
    for (let round = 1; round <= 9; round++) {
      this._subBytes(state);
      this._shiftRows(state);
      this._mixColumns(state);
      this._addRoundKey(state, round);
    }
    this._subBytes(state);
    this._shiftRows(state);
    this._addRoundKey(state, 10);

    return state;
  }

  _addRoundKey(state, round) {
    const offset = round * 16;
    for (let i = 0; i < 16; i++) {
      state[i] ^= this._roundKeys[offset + i];
    }
  }

  _subBytes(state) {
    for (let i = 0; i < 16; i++) {
      state[i] = SBOX[state[i]];
    }
  }

  _shiftRows(state) {
    // Row r is cyclically shifted left by r positions (column-major layout)
    const copy = new Uint8Array(state);
    for (let r = 1; r < 4; r++) {
      for (let c = 0; c < 4; c++) {
        state[c * 4 + r] = copy[((c + r) % 4) * 4 + r];
      }
    }
  }

  _mixColumns(state) {
    for (let c = 0; c < 4; c++) {
      const i = c * 4;
      const a0 = state[i], a1 = state[i + 1], a2 = state[i + 2], a3 = state[i + 3];
      const t = a0 ^ a1 ^ a2 ^ a3;
      state[i]     ^= t ^ xtime(a0 ^ a1);
      state[i + 1] ^= t ^ xtime(a1 ^ a2);
      state[i + 2] ^= t ^ xtime(a2 ^ a3);
      state[i + 3] ^= t ^ xtime(a3 ^ a0);
    }
  }
}

// aes-cbc.mjs
// AES CBC mode of operation, mirroring the behavior of pyaes.AESModeOfOperationCBC:
// each encrypt() call consumes exactly one 16-byte block and the CBC chaining
// state is carried across calls (no padding).

import { AESBlockCipher } from './aes-core.mjs';

export class AESModeOfOperationCBC {
  /**
   * @param {Uint8Array} key - 16-byte AES key
   * @param {Uint8Array} iv  - 16-byte initialization vector
   */
  constructor(key, iv) {
    if (iv.length !== 16) {
      throw new Error('IV must be exactly 16 bytes');
    }
    this._cipher = new AESBlockCipher(key);
    this._previous = new Uint8Array(iv);
  }

  /**
   * Encrypt one 16-byte block; the resulting ciphertext becomes the
   * chaining value for the next call (CBC mode, stateful like pyaes).
   * @param {Uint8Array} data - 16-byte plaintext block
   * @returns {Uint8Array} 16-byte ciphertext block
   */
  encrypt(data) {
    if (data.length !== 16) {
      throw new Error('Data must be exactly 16 bytes for CBC without padding');
    }
    const xored = new Uint8Array(16);
    for (let i = 0; i < 16; i++) {
      xored[i] = data[i] ^ this._previous[i];
    }
    const ciphertext = this._cipher.encryptBlock(xored);
    this._previous = new Uint8Array(ciphertext);
    return ciphertext;
  }
}

// pybytes.mjs
// Reproduce Python 3's repr() of a bytes object, character for character.
// Examples: b'abc'  b'\x00\xff'  b"'" (uses double quotes when the data
// contains a single quote but no double quote).

const HEX = '0123456789abcdef';

/**
 * Format a byte buffer exactly as Python's print(bytes) would.
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function pyBytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  // Python prefers single quotes; switches to double quotes only when the
  // data contains a single quote and no double quote.
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  let out = 'b' + quoteChar;
  for (const b of bytes) {
    if (b === quote || b === 0x5c) {
      // escape the active quote char and the backslash
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + HEX[b >> 4] + HEX[b & 0x0f];
    }
  }
  out += quoteChar;
  return out;
}

// argparse.mjs
// Minimal command-line parser that mirrors the argparse behavior of the
// original Python script: four required string options (--key, --iv,
// --data1, --data2), support for "--opt value" and "--opt=value" forms,
// -h/--help, usage/error output, and exit code 2 on argument errors.

const PROG = 'test7.mjs';
const OPTIONS = ['key', 'iv', 'data1', 'data2'];

function usage() {
  return `usage: ${PROG} [-h] --key KEY --iv IV --data1 DATA1 --data2 DATA2`;
}

function errorExit(message) {
  console.error(usage());
  console.error(`${PROG}: error: ${message}`);
  process.exit(2);
}

/**
 * Parse argv (already sliced to the arguments, i.e. process.argv.slice(2)).
 * @param {string[]} argv
 * @returns {{key: string, iv: string, data1: string, data2: string}}
 */
export function parseArgs(argv) {
  const result = {};

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      console.log(usage());
      console.log('');
      console.log('options:');
      console.log('  -h, --help     show this help message and exit');
      console.log('  --key KEY');
      console.log('  --iv IV');
      console.log('  --data1 DATA1');
      console.log('  --data2 DATA2');
      process.exit(0);
    }

    let name = null;
    let value = null;

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        value = token.slice(eq + 1);
      } else {
        name = token.slice(2);
        if (i + 1 >= argv.length) {
          errorExit(`argument --${name}: expected one argument`);
        }
        value = argv[++i];
      }
    } else {
      errorExit(`unrecognized arguments: ${token}`);
    }

    if (!OPTIONS.includes(name)) {
      errorExit(`unrecognized arguments: --${name}`);
    }
    result[name] = value;
  }

  const missing = OPTIONS.filter((opt) => !(opt in result));
  if (missing.length > 0) {
    errorExit(
      'the following arguments are required: ' +
        missing.map((opt) => `--${opt}`).join(', ')
    );
  }

  return result;
}

// test7.mjs
// Node.js (ESM) port of test7.py — AES-128-CBC encryption of two 16-byte
// blocks with a stateful cipher, printing results as Python bytes reprs.

import { parseArgs } from './lib/argparse.mjs';
import { AESModeOfOperationCBC } from './lib/aes-cbc.mjs';
import { pyBytesRepr } from './lib/pybytes.mjs';

function encode(str) {
  // Matches Python's str.encode() (UTF-8) for the arguments used here.
  return new Uint8Array(Buffer.from(str, 'utf8'));
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  // Create AES CBC cipher (stateful, like pyaes: ciphertext of block 1
  // is the chaining value for block 2)
  const aes = new AESModeOfOperationCBC(encode(args.key), encode(args.iv));

  // Encrypt two data blocks
  const ciphertext1 = aes.encrypt(encode(args.data1));
  const ciphertext2 = aes.encrypt(encode(args.data2));

  console.log(pyBytesRepr(ciphertext1));
  console.log(pyBytesRepr(ciphertext2));
}

main();

